//! The operations catalog: every GoHighLevel endpoint, from the official OpenAPI specs.
//!
//! This backs the meta-tools (`ghl_search_operations`, `ghl_describe_operation`,
//! `ghl_execute_operation`) so agents reach the whole API surface without the
//! server defining hundreds of individual tools. The catalog is generated by
//! `xtask/build-index` from <https://github.com/GoHighLevel/highlevel-api-docs>
//! and embedded in the binary — no network fetch, no runtime dependency.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

/// Generated at build time from the official specs.
const CATALOG_JSON: &str = include_str!("../operations.json");

/// One API operation (endpoint + method) with the metadata agents need.
#[derive(Debug, Clone, Deserialize)]
pub struct Operation {
    /// Stable identifier, e.g. `contacts.post_contacts`.
    pub id: String,
    /// Owning API module, e.g. `contacts`.
    pub module: String,
    /// HTTP method, uppercase.
    pub method: String,
    /// Path template, e.g. `/contacts/{contactId}`.
    pub path: String,
    /// Short human summary from the spec.
    #[serde(default)]
    pub summary: String,
    /// Longer description, when the spec has one.
    #[serde(default)]
    pub desc: Option<String>,
    /// Path and query parameters.
    #[serde(default)]
    pub params: Vec<Param>,
    /// Request body shape, for write operations.
    #[serde(default)]
    pub body: Option<BodyInfo>,
    /// OAuth scopes the endpoint requires.
    #[serde(default)]
    pub scopes: Vec<String>,
    /// `Version` header value this endpoint expects, when it differs.
    #[serde(default)]
    pub version: Option<String>,
}

/// A path or query parameter.
#[derive(Debug, Clone, Deserialize)]
pub struct Param {
    /// Parameter name as sent on the wire.
    pub name: String,
    /// Either `path` or `query`.
    #[serde(rename = "in")]
    pub location: String,
    /// Whether the API requires it.
    #[serde(default)]
    pub required: bool,
    /// JSON type from the spec.
    #[serde(default)]
    pub r#type: String,
    /// Spec description, when present.
    #[serde(default)]
    pub desc: Option<String>,
}

/// Top-level request-body information (field names only — not full schemas).
#[derive(Debug, Clone, Deserialize)]
pub struct BodyInfo {
    /// Top-level field names accepted by the endpoint.
    #[serde(default)]
    pub fields: Vec<String>,
    /// Which of those fields are required.
    #[serde(default)]
    pub required: Vec<String>,
    /// Schema component name, when the spec only referenced one.
    #[serde(default)]
    pub r#ref: Option<String>,
}

#[derive(Debug, Deserialize)]
struct Catalog {
    operation_count: usize,
    modules: BTreeMap<String, usize>,
    operations: Vec<Operation>,
}

fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| {
        serde_json::from_str(CATALOG_JSON).expect("embedded operations.json is valid")
    })
}

/// Total number of catalogued operations.
pub fn operation_count() -> usize {
    catalog().operation_count
}

/// Module name → operation count.
pub fn modules() -> &'static BTreeMap<String, usize> {
    &catalog().modules
}

/// Look up one operation by its exact id.
pub fn find(id: &str) -> Option<&'static Operation> {
    catalog().operations.iter().find(|o| o.id == id)
}

/// Rank operations against a free-text query.
///
/// Scoring favours exact id matches, then module matches, then summary hits, so
/// `"create contact"` surfaces `contacts.post_contacts` ahead of incidental
/// mentions of contacts elsewhere.
pub fn search(query: &str, module: Option<&str>, limit: usize) -> Vec<&'static Operation> {
    let needle = query.trim().to_lowercase();
    let terms: Vec<&str> = needle.split_whitespace().collect();

    let mut scored: Vec<(i32, &'static Operation)> = catalog()
        .operations
        .iter()
        .filter(|o| module.is_none_or(|m| o.module.eq_ignore_ascii_case(m)))
        .filter_map(|o| {
            if terms.is_empty() {
                return Some((0, o));
            }
            let id = o.id.to_lowercase();
            let summary = o.summary.to_lowercase();
            let path = o.path.to_lowercase();
            let mut score = 0;
            let mut matched_all = true;

            for term in &terms {
                let mut hit = 0;
                if id == *term {
                    hit += 100;
                }
                if id.contains(term) {
                    hit += 12;
                }
                if o.module.to_lowercase().contains(term) {
                    hit += 8;
                }
                if summary.contains(term) {
                    hit += 6;
                }
                if path.contains(term) {
                    hit += 4;
                }
                // Method aliases: "create" -> POST, "update" -> PUT/PATCH, etc.
                let method_hit = match *term {
                    "create" | "add" | "send" | "new" => o.method == "POST",
                    "update" | "edit" | "change" | "move" => {
                        o.method == "PUT" || o.method == "PATCH"
                    }
                    "delete" | "remove" => o.method == "DELETE",
                    "get" | "list" | "search" | "fetch" | "read" | "find" => o.method == "GET",
                    _ => false,
                };
                if method_hit {
                    hit += 5;
                }
                if hit == 0 {
                    matched_all = false;
                } else {
                    score += hit;
                }
            }
            // Require every term to land somewhere, so results stay precise.
            (matched_all && score > 0).then_some((score, o))
        })
        .collect();

    scored.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.id.cmp(&b.1.id)));
    scored.into_iter().take(limit).map(|(_, o)| o).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_loads_and_covers_all_modules() {
        assert!(operation_count() > 500, "expected the full API surface");
        assert_eq!(modules().len(), 41, "all 41 GoHighLevel modules present");
        // Spot-check a few modules the hand-written SDK does not cover.
        for m in ["invoices", "calendars", "payments", "workflows", "objects"] {
            assert!(modules().contains_key(m), "missing module {m}");
        }
    }

    #[test]
    fn search_ranks_relevant_operations_first() {
        let hits = search("create contact", None, 5);
        assert!(!hits.is_empty());
        let top = hits[0];
        assert_eq!(top.method, "POST");
        assert!(top.module == "contacts", "got {}", top.id);
    }

    #[test]
    fn search_can_filter_by_module() {
        let hits = search("", Some("invoices"), 500);
        assert!(hits.len() > 10);
        assert!(hits.iter().all(|o| o.module == "invoices"));
    }

    #[test]
    fn find_resolves_known_ids_and_rejects_unknown() {
        let id = &search("", Some("contacts"), 1)[0].id;
        assert!(find(id).is_some());
        assert!(find("nope.not_real").is_none());
    }

    #[test]
    fn every_operation_has_a_usable_shape() {
        for o in &catalog().operations {
            assert!(o.path.starts_with('/'), "{} has odd path", o.id);
            assert!(
                ["GET", "POST", "PUT", "PATCH", "DELETE"].contains(&o.method.as_str()),
                "{} has odd method {}",
                o.id,
                o.method
            );
        }
    }
}
